<script lang="ts">
  import {tick,untrack} from 'svelte';
  import {tr as i18n,locale} from '$lib/i18n/language';
  import ChatIcon from '$lib/chat/ChatIcon.svelte';
  import MessageText from '$lib/chat/MessageText.svelte';
  import MessageCard from '$lib/chat/MessageCard.svelte';
  import MessageTools from '$lib/chat/MessageTools.svelte';
  import MessageSelectionBar from '$lib/chat/MessageSelectionBar.svelte';
  import ChatSearch from '$lib/chat/ChatSearch.svelte';
  import EmojiPicker from '$lib/chat/EmojiPicker.svelte';
  import HistoryDivider from '$lib/chat/HistoryDivider.svelte';
  import RadioAvatar from './RadioAvatar.svelte';
  import HelpInfo from '$lib/application/HelpInfo.svelte';
  import RadioReception from './RadioReception.svelte';
  import RadioBoardName from './RadioBoardName.svelte';
  import ChannelSecurity from './ChannelSecurity.svelte';
  import {CHANNEL_TEXT_BYTES,channelText,channelSignature,nativeMessageKey,nativeChatEntry,nativeMessageStatus,nativeFailureAction,type NativeChannels,type NativeChannel,type ChannelMessage} from './native-channels';
  let {data,selected,live,connected,busy,board,link,initialUnread=0,forwardDone=0,onSignature,onSend,onSettings,onBack,onDelete,onDraft,onForward,onBottom}:
    {data:NativeChannels;selected:string;live:string[];connected:boolean;busy:boolean;board:string;link:string;initialUnread?:number;forwardDone?:number;
      onSignature(c:NativeChannel,value:boolean):Promise<void>;
      onSend(c:NativeChannel,text:string,options?:{replyId?:number;retryOf?:number;literal?:boolean}):Promise<void>;
      onSettings():void;onBack():void;onDelete(c:NativeChannel,ids:string[]):Promise<void>;
      onDraft(c:NativeChannel,text:string,replyId?:number):void;onForward(c:NativeChannel,messages:ChannelMessage[]):void;onBottom(value:boolean):void}=$props();
  const token=(c:NativeChannel)=>`${c.node}:${c.key}`;
  const current=$derived(data.channels.find(c=>token(c)===selected));
  const entries=$derived((current?.messages??[]).map(nativeChatEntry));
  const draft=$derived(current?.draft??'');
  const reply=$derived(current?.messages.find(m=>m.id===current.replyId));
  let error=$state(''),notice=$state(''),working=$state(false),history=$state<HTMLDivElement>(),composer=$state<HTMLTextAreaElement>();
  let optionsOpen=$state(false),menu=$state<{id:string;view:'menu'|'status'|'route'|'share'}|null>(null),emojiOpen=$state(false),channelMenu=$state(false);
  let selecting=$state(false),chosen=$state<string[]>([]),confirmDelete=$state<string[]|null>(null),retry=$state<ChannelMessage|null>(null);
  let search=$state(false),searchPosition=0,highlighted=$state(''),nearBottom=$state(true),jumpVisible=$state(false);
  let boundary=$state('');
  const chosenMessages=$derived(current?.messages.filter(m=>chosen.includes(nativeMessageKey(m)))??[]);
  const available=$derived(connected&&!!current&&live.includes(token(current))&&data.enabled);
  const composed=$derived.by(()=>{try{return channelText(draft,current?.signature??false,link);}catch{return '';}});
  const bytes=$derived(new TextEncoder().encode(draft.trim()+(current?.signature?`\n${channelSignature(link)}`:'')).length);
  $effect(()=>{const key=selected;untrack(()=>{const incoming=current?.messages.filter(m=>!m.outgoing)??[];boundary=initialUnread&&incoming.length?nativeMessageKey(incoming.at(-initialUnread)??incoming[0]):'';nearBottom=true;void tick().then(()=>bottom(false));});});
  $effect(()=>{const last=current?.messages.at(-1);void last;untrack(()=>{if(nearBottom&&!search)void tick().then(()=>bottom(false));});});
  $effect(()=>{void forwardDone;untrack(()=>{chosen=[];selecting=false;});});
  function day(time:number){return new Date(time).toDateString();}
  function scrollState(){if(!history)return;nearBottom=history.scrollHeight-history.scrollTop-history.clientHeight<90;onBottom(nearBottom);const items=[...history.querySelectorAll<HTMLElement>('[data-native-id]')];jumpVisible=items.filter(item=>item.offsetTop+item.offsetHeight>history!.scrollTop+history!.clientHeight).length>=12;}
  function bottom(smooth=true){if(!history)return;history.scrollTo({top:history.scrollHeight,behavior:smooth?'smooth':'instant'});nearBottom=true;jumpVisible=false;onBottom(true);}
  function watchHistory(node:HTMLDivElement){const observer=new ResizeObserver(()=>{if(nearBottom&&!search)bottom(false);});observer.observe(node);return{destroy(){observer.disconnect();}};}
  function jump(id:string){const item=[...history?.querySelectorAll<HTMLElement>('[data-native-id]')??[]].find(n=>n.dataset.nativeId===id);if(!item){notice='Исходное сообщение удалено или отсутствует на этом устройстве.';return;}nearBottom=false;history?.scrollTo({top:item.offsetTop-((history.clientHeight-item.offsetHeight)/2),behavior:'smooth'});highlighted=id;setTimeout(()=>{if(highlighted===id)highlighted='';},1800);}
  function toggleSearch(){if(!search){searchPosition=history?.scrollTop??0;search=true;}else{search=false;void tick().then(()=>{history?.scrollTo({top:searchPosition});scrollState();});}}
  function select(id:string){if(working)return;chosen=chosen.includes(id)?chosen.filter(k=>k!==id):[...chosen,id];}
  function beginSelect(m:ChannelMessage){selecting=true;chosen=[nativeMessageKey(m)];}
  function setDraft(text:string,replyId=current?.replyId){if(current)onDraft(current,text,replyId);}
  async function action(work:()=>Promise<void>){if(working)return;working=true;error='';notice='';try{await work();}catch(e){error=e instanceof Error?e.message:'Не удалось выполнить действие.';}finally{working=false;}}
  function success(){chosen=[];selecting=false;error='';}
  async function copy(messages:ChannelMessage[]){await action(async()=>{await navigator.clipboard.writeText(messages.map(m=>m.text).join('\n\n'));notice='Текст скопирован.';success();});}
  function transcript(messages:ChannelMessage[]){return messages.map(m=>`[${new Date(m.timestamp).toLocaleString()}] ${m.name||'!'+m.from.toString(16)}\n${m.text}`).join('\n\n');}
  async function download(messages:ChannelMessage[]){await action(async()=>{const url=URL.createObjectURL(new Blob([transcript(messages)],{type:'text/plain;charset=utf-8'}));try{const a=document.createElement('a');a.href=url;a.download=`Meshtastic-${current?.node}-${Date.now()}.txt`;a.click();notice='Файл передан браузеру для скачивания.';success();}finally{setTimeout(()=>URL.revokeObjectURL(url),60000);}});}
  function startReply(m:ChannelMessage){if(current)onDraft(current,draft,m.id);composer?.focus();}
  async function send(){if(optionsOpen||!current||!available||!composed||working||busy)return;const c=current,text=draft,replyId=c.replyId;await action(async()=>{await onSend(c,text,{replyId});if(current&&token(c)===token(current)&&current.draft===text)onDraft(current,'');nearBottom=true;});}
  function addEmoji(value:string){const start=composer?.selectionStart??draft.length,end=composer?.selectionEnd??start;setDraft((draft.slice(0,start)+value+draft.slice(end)).slice(0,600));void tick().then(()=>{composer?.focus();composer?.setSelectionRange(start+value.length,start+value.length);});}
  function modal(node:HTMLDialogElement){const previous=document.activeElement as HTMLElement|null;node.showModal();return{destroy(){node.close();if(previous?.isConnected)previous.focus();}};}
  function sendPress(node:HTMLButtonElement){
    let timer:ReturnType<typeof setTimeout>|undefined,held=false,x=0,y=0;
    const stop=()=>{clearTimeout(timer);timer=undefined;};
    const down=(event:PointerEvent)=>{if(event.button!==0||node.disabled)return;stop();held=false;x=event.clientX;y=event.clientY;timer=setTimeout(()=>{held=true;optionsOpen=true;},500);};
    const move=(event:PointerEvent)=>{if(Math.hypot(event.clientX-x,event.clientY-y)>10)stop();};
    const cancel=()=>{stop();held=false;};
    const click=(event:MouseEvent)=>{stop();if(held){held=false;event.preventDefault();event.stopImmediatePropagation();}};
    node.addEventListener('pointerdown',down);window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);window.addEventListener('pointercancel',cancel);window.addEventListener('blur',cancel);node.addEventListener('click',click,true);
    return{destroy(){stop();node.removeEventListener('pointerdown',down);window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);window.removeEventListener('pointercancel',cancel);window.removeEventListener('blur',cancel);node.removeEventListener('click',click,true);}};
  }
</script>
<div class="native-channels">
  <header class="heading"><button class="icon" onclick={()=>{if(selecting){selecting=false;chosen=[];}else onBack();}} aria-label={$i18n.text(selecting?'Отменить выбор':'Все чаты')}>←</button><span class="radio-avatar"><ChatIcon name="radio"/></span><div class="title"><strong><RadioBoardName name={current?.name||$i18n.text('По умолчанию')}/></strong><small>LoRa · Meshtastic · <RadioBoardName name={current?.boardName||board||`!${current?.node.toString(16)}`}/></small></div>
    {#if !selecting}<button class="icon" onclick={toggleSearch} aria-label={$i18n.text('Поиск в чате')}><ChatIcon name="search"/></button><button class="icon" onclick={()=>{selecting=true;chosen=[];}} aria-label={$i18n.text('Выбрать сообщения')}><ChatIcon name="select"/></button><button class="icon" onclick={()=>channelMenu=!channelMenu} aria-label={$i18n.text('Меню канала')}>⋯</button>{/if}
  </header>
  {#if selecting}<MessageSelectionBar messages={entries} selected={chosen} busy={working} onToggleAll={()=>chosen=chosen.length===entries.length?[]:entries.map(m=>m.id)} onCopy={()=>void copy(chosenMessages)} onForward={()=>current&&onForward(current,chosenMessages)} onDownload={()=>void download(chosenMessages)} onDelete={()=>confirmDelete=[...chosen]}/>{/if}
  {#if search}<ChatSearch messages={entries} onJump={jump} onClose={toggleSearch}/><small>{$i18n.text('Поиск только в сохранённой истории этого канала.')}</small>{/if}
  {#if channelMenu&&current}<section class="channel-menu"><ChannelSecurity value={current.encryption}/><small>{$i18n.text('Отправитель — плата Meshtastic')} · {$i18n.text(available?'Подключён':'Радиомодуль отключён')}</small><div class="actions"><button onclick={onSettings}>{$i18n.text('Настройки LoRa')}</button><button disabled={working||!current.messages.length} onclick={()=>confirmDelete=current!.messages.map(nativeMessageKey)}>{$i18n.text('Очистить историю')}</button></div><HelpInfo label={$i18n.text('О каналах Meshtastic')} text={$i18n.text('Общеизвестный ключ не обеспечивает приватность. Собственный ключ ограничивает круг читателей, но не подтверждает личность отправителя. Подтверждение сети не означает получение всеми участниками или прочтение. История и черновики хранятся в этом профиле.')} /></section>{/if}
  {#if !available}<div class="connection-note"><span>{$i18n.text(connected?'Для отправки подключите плату этого канала.':'Радиомодуль отключён')}</span><button onclick={onSettings}>{$i18n.text('Подключить')}</button></div>{/if}
  <div class="history-wrap"><div class="history" bind:this={history} onscroll={scrollState}><div use:watchHistory>
    {#if current}{#each current.messages as m,i (nativeMessageKey(m))}
      {#if i===0||day(m.timestamp)!==day(current.messages[i-1].timestamp)}<HistoryDivider timestamp={m.timestamp}/>{/if}
      {#if boundary===nativeMessageKey(m)}<HistoryDivider unread/>{/if}
      <div class="message-anchor" data-native-id={nativeMessageKey(m)}>
      <MessageCard outgoing={m.outgoing} {selecting} selected={chosen.includes(nativeMessageKey(m))} highlighted={highlighted===nativeMessageKey(m)} busy={working} preview={m.text} onSelect={()=>select(nativeMessageKey(m))} onBeginSelect={()=>beginSelect(m)}>
        <div class="message-heading"><RadioAvatar node={m.from} size={18}/><strong><RadioBoardName name={m.name||`!${m.from.toString(16).padStart(8,'0')}`}/></strong><time datetime={new Date(m.timestamp).toISOString()} title={new Date(m.timestamp).toLocaleString($locale)}>{new Date(m.timestamp).toLocaleTimeString($locale,{hour:'2-digit',minute:'2-digit'})}</time><button class="tiny" onclick={()=>startReply(m)} aria-label={$i18n.text('Ответить')}><ChatIcon name="reply"/></button><button class="tiny" onclick={()=>void copy([m])} aria-label={$i18n.text('Скопировать текст')}><ChatIcon name="copy"/></button>
        <MessageTools message={nativeChatEntry(m)} status={nativeMessageStatus(m)} recipient={current.name} shareText={m.text} openView={menu?.id===nativeMessageKey(m)?menu.view:null} disabled={working} canReply={true} channelMode canPin={false}
          onOpen={view=>menu={id:nativeMessageKey(m),view}} onClose={()=>menu=null} onReply={()=>startReply(m)} onForward={()=>current&&onForward(current,[m])} onSelect={()=>beginSelect(m)} onStop={()=>{}} onDownload={()=>void download([m])} onDelete={()=>confirmDelete=[nativeMessageKey(m)]} onPin={()=>{}} loadShareFile={async()=>{throw Error('Только текст');}} onCopy={()=>void copy([m])} onRetryChannel={m.outgoing&&m.status!=='queued'&&available&&!busy?()=>retry=m:undefined}/></div>
        {#if m.replyId}{@const originals=current.messages.filter(x=>x.id===m.replyId)}<button class="quote" onclick={()=>originals.length===1?jump(nativeMessageKey(originals[0])):notice='Исходное сообщение удалено или отсутствует на этом устройстве.'}><small>↩ {$i18n.text('Ответить')}</small><span>{originals.length===1?originals[0].text:$i18n.text('Исходное сообщение отсутствует')}</span></button>{/if}
        {#if m.retryOf}<small>{$i18n.text('Повторная отправка')}</small>{/if}
        <p><MessageText text={m.text} markdownLinks/></p>{#if m.reception&&!m.outgoing}<RadioReception reception={m.reception}/>{/if}
        {#if m.outgoing}{@const status=nativeMessageStatus(m)}<button class="status" class:success={status.tone==='success'} class:danger={status.tone==='error'} onclick={()=>menu={id:nativeMessageKey(m),view:'status'}}>{status.icon} {$i18n.system(status.label)}</button>{/if}
        {#if m.status==='failed'}<div class="failure-action"><small>{$i18n.system(nativeMessageStatus(m).detail)}</small>{#if nativeFailureAction(m.failure)==='connect'}<button onclick={onSettings}>{$i18n.text('Подключить')}</button>{:else if nativeFailureAction(m.failure)==='wait'}<small>{$i18n.text('Дождитесь освобождения очереди или разрешённого времени передачи, затем повторите.')}</small>{:else if nativeFailureAction(m.failure)==='shorten'}<button onclick={()=>{setDraft(m.text);composer?.focus();}}>{$i18n.text('Сократить текст')}</button>{:else}<button disabled={!available||busy||working} onclick={()=>retry=m}>{$i18n.text('Отправить снова')}</button>{/if}</div>{/if}
      </MessageCard></div>
    {:else}<p class="empty">{$i18n.text('В этом радиоканале пока нет сообщений.')}</p>{/each}{/if}
  </div></div>{#if jumpVisible||!nearBottom&&(current?.unread??0)>0}<button class="jump" onclick={()=>bottom()} aria-label={$i18n.text('К последним сообщениям')}>↓{#if current?.unread}<span>{current.unread}</span>{/if}</button>{/if}</div>
  {#if error}<p class="error" role="alert">{$i18n.system(error)}</p>{/if}{#if notice}<small role="status">{$i18n.system(notice)}</small>{/if}
  {#if current?.replyId}<div class="reply-draft"><span>↩ {reply?.text||$i18n.text('Исходное сообщение отсутствует')}</span><button onclick={()=>current&&onDraft(current,draft)} aria-label={$i18n.text('Отменить ответ')}>✕</button></div>{/if}
  {#if emojiOpen}<EmojiPicker onChoose={addEmoji} onClose={()=>emojiOpen=false}/>{/if}
  <form onsubmit={e=>{e.preventDefault();void send();}}><div class="composer"><textarea bind:this={composer} value={draft} oninput={e=>setDraft(e.currentTarget.value)} maxlength="600" aria-label={$i18n.text('Сообщение в канал Meshtastic')} placeholder={$i18n.text('Короткое сообщение от имени платы')} onkeydown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void send();}}}></textarea><button type="button" class="tiny" onclick={()=>emojiOpen=!emojiOpen} aria-label={$i18n.text('Эмодзи')}><ChatIcon name="emoji"/></button></div><button type="button" class="icon primary" class:send-unavailable={!available||!composed} use:sendPress onclick={()=>void send()} oncontextmenu={e=>{e.preventDefault();if(current&&!working&&!busy)optionsOpen=true;}} disabled={!current||working||busy} aria-label={$i18n.text('Отправить')} aria-haspopup="dialog" aria-expanded={optionsOpen} title={$i18n.text('Удерживайте кнопку для настроек отправки')}><ChatIcon name="send"/></button></form>
  <small class:danger={bytes>CHANNEL_TEXT_BYTES}>{bytes}/{CHANNEL_TEXT_BYTES} {$i18n.text('байт')}</small>
  {#if optionsOpen&&current}<dialog use:modal aria-label={$i18n.text('Настройки отправки')} oncancel={e=>{e.preventDefault();if(!working)optionsOpen=false;}}><header><h3>{$i18n.text('Настройки отправки')}</h3><button disabled={working} onclick={()=>optionsOpen=false} aria-label={$i18n.text('Закрыть')}>✕</button></header><label class="check"><input type="checkbox" checked={current.signature} disabled={working||busy} onchange={e=>void action(()=>onSignature(current!,e.currentTarget.checked))}/>{$i18n.text('Добавлять мой контакт Automesh')}</label>{#if current.signature}<p class="signature-preview"><MessageText text={channelSignature(link)} markdownLinks/></p>{/if}<p>{$i18n.text('Ссылка будет видна всем читателям канала и входит в лимит сообщения.')}</p><small>{bytes}/{CHANNEL_TEXT_BYTES} {$i18n.text('байт')}</small><footer><button disabled={working} onclick={()=>optionsOpen=false}>{$i18n.text('Готово')}</button></footer></dialog>{/if}
  {#if confirmDelete&&current}<dialog use:modal aria-label={$i18n.text('Удалить выбранные сообщения?')} oncancel={e=>{e.preventDefault();if(!working){confirmDelete=null;error='';}}}><h3>{$i18n.text('Удалить выбранные сообщения?')}</h3><p>{$i18n.text('Только из истории Automesh. Копии на платах и у участников сохранятся; отправку в эфир это не отменяет.')}</p>{#if error}<p class="error">{$i18n.system(error)}</p>{/if}<footer><button disabled={working} onclick={()=>void action(async()=>{await onDelete(current!,confirmDelete!);confirmDelete=null;success();notice='Сообщения удалены только у вас.';})}>{$i18n.text('Удалить у меня')}</button><button disabled={working} onclick={()=>{confirmDelete=null;error='';}}>{$i18n.text('Отмена')}</button></footer></dialog>{/if}
  {#if retry&&current}<dialog use:modal aria-label={$i18n.text('Отправить снова')} oncancel={e=>{e.preventDefault();if(!working)retry=null;}}><h3>{$i18n.text('Отправить снова')}</h3><p>{$i18n.text('Сообщение могло уже дойти. Повтор создаст новую отправку и может быть виден участникам дважды.')}</p><p class="quote">{retry.text}</p>{#if error}<p class="error">{$i18n.system(error)}</p>{/if}<footer><button disabled={!available||working||busy} onclick={()=>void action(async()=>{const m=retry!;retry=null;await onSend(current!,m.text,{replyId:m.replyId,retryOf:m.id,literal:true});success();})}>{$i18n.text('Отправить снова')}</button><button disabled={working} onclick={()=>retry=null}>{$i18n.text('Отмена')}</button></footer></dialog>{/if}
</div>
<style>
 .native-channels{height:100%;min-height:0;display:flex;flex-direction:column;gap:6px;padding:0 2px;min-width:0}.heading{display:flex;align-items:center;gap:6px}.title{min-width:0;flex:1}.title strong{font-size:18px}.title small{display:block;overflow-wrap:anywhere}.radio-avatar{display:grid;place-items:center;width:32px;height:32px;background:var(--accent-soft);border-radius:8px;color:var(--accent);flex-shrink:0}.icon{display:grid;place-items:center;width:44px;height:44px;min-width:44px;padding:6px}.tiny{display:inline-grid;place-items:center;width:32px;height:32px;min-width:32px;border:0;background:transparent;padding:5px}.history-wrap{flex:1;min-height:100px;position:relative}.history{position:absolute;inset:0;overflow:auto;border:1px solid var(--line);border-radius:12px;padding:10px;background:var(--surface-alt)}.message-anchor{position:relative}.message-heading{display:flex;align-items:center;gap:5px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.message-heading strong{max-width:110px;overflow-wrap:anywhere}.message-heading time{margin-right:auto}.message-heading :global(.trigger){min-width:28px;min-height:32px}.message-heading .tiny{width:28px;min-width:28px}.status{display:block;text-align:right;margin-left:auto;font-size:11px;color:var(--warning);border:0;background:transparent;padding:4px 0}.success{color:var(--success)}.danger,.error{color:var(--danger)}small{font-size:11px;color:var(--muted)}p{margin:8px 0;white-space:pre-wrap}.quote,.reply-draft{display:block;border:0;border-left:3px solid var(--accent);background:var(--surface-alt);padding:6px 9px;text-align:left;max-width:100%;box-sizing:border-box;overflow-wrap:anywhere}.quote span{display:block;max-height:44px;overflow:hidden}.quote small{display:block}.reply-draft{display:flex;justify-content:space-between;gap:8px}.reply-draft span{max-height:44px;overflow:hidden}.reply-draft button{border:0;background:transparent}.jump{position:absolute;bottom:12px;right:14px;border-radius:50%;min-width:44px;height:44px;box-shadow:0 2px 8px var(--overlay)}.jump span{font-size:11px;margin-left:4px}.channel-menu{display:grid;gap:8px;border:1px solid var(--line);padding:10px;border-radius:12px}.actions{display:flex;gap:6px;flex-wrap:wrap}.connection-note{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted)}.connection-note button{font-size:11px;padding:4px 8px}.empty{color:var(--muted);font-size:13px}.error{font-size:12px;margin:0}.check{display:flex;align-items:center;gap:8px}.send-unavailable{opacity:.55}form{display:flex;gap:6px;align-items:flex-end}.composer{display:flex;align-items:flex-end;flex:1;min-width:0;border:1px solid var(--line);border-radius:10px;background:var(--surface)}textarea{resize:none;min-height:44px;max-height:120px;width:100%;min-width:0;font:inherit;font-size:14px;border:0;background:transparent;box-sizing:border-box}button{font-size:13px}.failure-action{display:grid;gap:6px;margin-top:6px}.failure-action button{font-size:11px;justify-self:start}dialog{width:min(420px,calc(100vw - 24px));max-height:85dvh;overflow:auto;box-sizing:border-box}dialog header,footer{display:flex;align-items:center;justify-content:space-between;gap:8px}dialog h3{margin:0;font-size:17px}dialog .check{margin:16px 0}dialog p{font-size:13px;line-height:1.5}.signature-preview{overflow-wrap:anywhere}footer{justify-content:flex-end;margin-top:14px}@media(max-width:450px){.heading{gap:4px}.icon{width:36px;min-width:36px;height:40px}.title strong{font-size:16px}.title small{font-size:10px}}
</style>
